def pfit(transitive, rots):
    shape=[(0,0),(1,0),(1,1),(2,0),(2,1)]
    def rots_of(sh):
        out=[]
        cur=sh
        for _ in range(4):
            out.append(cur)
            cur=[(j,-i) for i,j in cur]
        # normalize
        def norm(s):
            mi=min(a for a,b in s); mj=min(b for a,b in s)
            return tuple(sorted((a-mi,b-mj) for a,b in s))
        return {norm(s) for s in out}
    shapes=rots_of(shape) if rots else {tuple(sorted(shape))}
    filled=set((i,j) for i in range(H) for j in range(W) if inp[i][j]==4)
    changed=True
    while changed:
        changed=False
        for i in range(H):
            for j in range(W):
                for sh in shapes:
                    cells=[(i+a,j+b) for a,b in sh]
                    if all(0<=a<H and 0<=b<W for a,b in cells) and all(inp[a][b]==0 and ((a,b) in filled or not transitive) for a,b in cells):
                        if not set(cells)<=filled:
                            filled|=set(cells); changed=True
    return filled
